/* ============================================================== rail + footer */

function buildRail(root) {
  const rail = document.getElementById('rail');
  if (!rail) return;
  rail.replaceChildren();
  const inner = el('div', 'rail-inner');
  const head = el('div', 'rail-head');
  head.append(el('div', 'rail-title', 'On this page'));
  inner.append(head);
  const list = el('div', 'rail-list');
  const links = new Map();
  for (const sec of root.querySelectorAll('section')) {
    if (!sec.dataset.title) continue;
    const link = el('a', 'rail-link');
    link.href = `#${sec.id}`;
    const body = el('span', 'rail-body');
    body.append(el('span', 'rail-t', sec.dataset.title));
    if (sec.dataset.sub) body.append(el('span', 'rail-sub', sec.dataset.sub));
    /* `rail-n` and `rail-body` are SIBLINGS: `.rail-link` is a two-column grid, and nesting the
     * number inside the body squeezes every title into the 16px number column. */
    link.append(el('span', 'rail-n', sec.dataset.n), body);
    list.append(link);
    links.set(sec.id, link);
  }
  inner.append(list);
  rail.append(inner);
  markPosition(root, links);
}

/* The shared stylesheet has styled `.rail-link.on` since before any of these pages existed, and
 * only exercise 03 ever set it — so 05, 06 and 07 all ship a rail that never says where you are.
 * The observer is registered here, from the code that has already appended the sections, because
 * an IntersectionObserver on a detached node never fires and says nothing. */
function markPosition(root, links) {
  const sections = [...root.querySelectorAll('section')].filter((s) => links.has(s.id));
  if (!sections.length || typeof IntersectionObserver !== 'function') return;

  const visible = new Set();
  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) visible.add(entry.target.id);
        else visible.delete(entry.target.id);
      }
      const current = sections.find((s) => visible.has(s.id));
      for (const [id, link] of links) link.classList.toggle('on', Boolean(current) && id === current.id);
    },
    { rootMargin: '-10% 0px -70% 0px', threshold: 0 }
  );
  for (const s of sections) observer.observe(s);
}

function buildFooter() {
  const f = document.getElementById('foot');
  if (!f) return;
  const p = el('p', 'say small');
  p.innerHTML =
    'Written for whoever arrives first: the argument is in plain words, and every number behind it ' +
    'is three commands away. ' +
    '<a href="https://github.com/pankajkr23/llm-pretraining-exercises/tree/main/src/exercises/09-loss-functions-output-heads">Code, tests and the full write-up</a>.';
  f.append(p);
}

export function buildPage(M) {
  chapterThesis(M);
  chapterGlossary(M);
  chapterProblem(M);
  chapterMechanism(M);
  chapterMethod(M);
  chapterExpected(M);
  chapterResults(M);
  chapterNegatives(M);
  chapterConclusion(M);
  chapterLimits(M);
  chapterNext();
  chapterReproduce();
  buildRail(main());
  buildFooter();
}
